/**
 * config.js — binary task
 * Sequences loaded from task/sequences/binary_sequences.json
 * (single master copy — generated by task/generate_sequences_momentmatch.py)
 * p_range=0.1..0.9, values {-1,+1}
 *
 * Common structure lives in shared/config-base.js — this file supplies only
 * what differs for the binary task.
 */
import sequencesData from '../../sequences/binary_sequences.json';
import { buildConfig, pickTutorialExample } from '../shared/config-base.js';

// Tutorial example is derived from a REAL main-task trial (closest true_p to
// 0.5, subject to a visual-spread check on the first 5 values) rather than
// hand-picked literals -- see config-base.js's pickTutorialExample and
// continuous/config.js's comment for why (this drifted out of sync once
// already on the continuous side).
const { values: tutorialValues, mean: TUTORIAL_P } =
  pickTutorialExample(sequencesData, { isBinary: true, n: 5 });

export const config = buildConfig({
  taskType:      'binary',
  sequencesData,
  tutorialValues,
  tutorialMean:  TUTORIAL_P,
  tutorialStd:   0,
  // No overrides — binary currently uses all shared defaults.
});
